{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, count(*) n, min(time) mn, max(time) mx, avg(value) v FROM abnormal_metrics WHERE service_name='attractions' AND metric='k8s.deployment.available' GROUP BY ALL", "claim": "Attractions deployment available count is 0 for the whole abnormal window, versus 1 in normal."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, attr_span_kind, span_name, count(*) n, min(time) mn, max(time) mx FROM abnormal_traces WHERE service_name='attractions' GROUP BY ALL UNION ALL SELECT 'norm', service_name, attr_span_kind, span_name, count(*), min(time), max(time) FROM normal_traces WHERE service_name='attractions' GROUP BY ALL", "claim": "Attractions emits no server spans in the abnormal window, while normal had about 340 across three span names."},
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE span_name LIKE 'attractions.Attractions/%' AND attr_span_kind='Client' GROUP BY ALL", "claim": "Every frontend client call to attractions.Attractions NearbyCinema, NearbyRest and NearbyMus errors, about 350 in total."}
      ]
    }
  ],
  "propagation": [
    {"from": "attractions", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND (span_name LIKE 'HTTP %' OR span_name LIKE 'attractions.%') AND attr_status_code='Error' GROUP BY ALL ORDER BY n DESC", "claim": "Frontend HTTP /cinema, /restaurants and /museums return 500 whenever their attractions calls fail."}]
    }
  ]
}
